(function editionRuntime(state, theme, editionName, resolveRoute) {
    const app = document.querySelector('[data-edition]');
    const views = [...document.querySelectorAll('[data-view]')];
    const seen = new Set();
    const positions = new Map();
    const directoryView = theme === 'flight' ? 'contents' : 'pages';
    let lastCoverTarget = 'about';
    let route = {view:theme === 'cobalt' ? 'pages' : 'cover', index:null};
    const routeKey = current => current.view === 'reader' ? 'reader/'+current.index : current.view;
    let previousKey = routeKey(resolveRoute(window.location.hash, state.entries.length, theme));
    let openTimer = null;
    const setText = (selector, value) => document.querySelectorAll(selector).forEach(node => {node.textContent=value;});

    function cancelTransition() {
        if (openTimer !== null) window.clearTimeout(openTimer);
        openTimer = null;
        app.classList.remove('is-opening');
        app.classList.remove('is-opening-about');
        app.classList.remove('is-opening-contents');
    }
    function fillReader(index) {
        const entry = state.entries[index];
        if (!entry) return;
        setText('[data-reader-title]', entry.title || '未命名开场');
        setText('[data-reader-route]', entry.route || '未分类');
        setText('[data-reader-number]', String(index+1).padStart(2,'0'));
        setText('[data-reader-text]', entry.previewText || entry.summary || '暂无开场内容');
        const next = document.querySelector('[data-next-opening]');
        next.hidden = index+1 >= state.entries.length;
        if (next.hidden) next.removeAttribute('href');
        else next.setAttribute('href', '#opening/'+(index+1));
    }
    function renderRoute(initial=false) {
        cancelTransition();
        const hash = window.location.hash || '#home';
        positions.set(previousKey, window.scrollY);
        const previous = route;
        route = resolveRoute(hash, state.entries.length, theme);
        if (theme === 'flight' && ['about','contents'].includes(route.view)) lastCoverTarget = route.view;
        views.forEach(node => {node.hidden = node.dataset.view !== route.view;});

        if (route.view === 'reader') {
            seen.add(route.index);
            fillReader(route.index);
            setText('[data-read-count]', String(seen.size).padStart(2,'0'));
            document.querySelectorAll('[data-entry]').forEach(node => {
                const isSeen = seen.has(Number(node.dataset.entry));
                node.classList.toggle('was-viewed', isSeen);
                node.querySelector('[data-entry-status]').textContent = isSeen ? '再读一遍' : '翻开';
            });
        }
        const pageTitle = route.view === 'reader' ? state.entries[route.index].title || '未命名开场' : state.title || '开场白';
        document.title = pageTitle+' · '+editionName;
        if (!initial) {
            const active = views.find(node => node.dataset.view === route.view);
            let target = active.querySelector('[data-page-heading]');
            if (route.view === directoryView && previous.view === 'reader') {
                const entryNode = [...active.querySelectorAll('[data-entry]')].find(node => Number(node.dataset.entry) === previous.index);
                const chapter = entryNode?.querySelector('[data-chapter]');
                if (chapter) chapter.open = true;
                target = [...active.querySelectorAll('[data-opening-index]')].find(node => Number(node.dataset.openingIndex) === previous.index) || target;
            }
            if (route.view === 'cover') target = theme === 'flight'
                ? [...active.querySelectorAll('[data-open-cover]')].find(link => link.dataset.openCover === lastCoverTarget) || target
                : active.querySelector('[data-open-cover]') || target;
            target?.focus({preventScroll:true});
            const returning = route.view === 'cover' || route.view === directoryView && previous.view === 'reader';
            window.scrollTo({top:returning ? positions.get(routeKey(route)) || 0 : 0, behavior:'instant'});
        }
        previousKey = routeKey(route);
    }
    document.querySelectorAll('[data-open-cover]').forEach(link => link.addEventListener('click', event => {
        if (event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey || route.view !== 'cover') return;
        if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
        event.preventDefault();
        if (openTimer !== null) return;
        const destination = link.getAttribute('href');
        if (theme === 'flight') {
            lastCoverTarget = link.dataset.openCover;
            app.classList.add('is-opening-'+lastCoverTarget);
        }
        app.classList.add('is-opening');
        openTimer = window.setTimeout(() => {
            openTimer = null;
            window.location.hash = destination;
        }, theme === 'flight' ? 680 : 560);
    }));
    window.addEventListener('hashchange', () => renderRoute());
    document.addEventListener('keydown', event => {
        if (event.key !== 'Escape' || /INPUT|TEXTAREA|SELECT/.test(event.target.tagName) || event.target.isContentEditable) return;
        if (openTimer !== null) {cancelTransition();return;}
        if (route.view === 'reader') window.location.hash = directoryView;
        else if (['pages','about','contents'].includes(route.view) && theme !== 'cobalt') window.location.hash = 'home';
    });
    document.querySelectorAll('[data-edit-home]').forEach(input => input.addEventListener('input', () => {
        const key=input.dataset.editHome;
        if (!Object.hasOwn(state,key) || key==='entries') return;
        state[key]=input.value;
        document.querySelectorAll('[data-home]').forEach(node => {
            if (node.dataset.home!==key) return;
            node.textContent=input.value;
            if (key==='title') node.classList.toggle('is-long',Array.from(input.value).length>6);
        });
        if (key==='title' && route.view!=='reader') document.title=(input.value||'开场白')+' · '+editionName;
    }));
    document.querySelectorAll('[data-edit-entry]').forEach(input => input.addEventListener('input', () => {
        const index=Number(input.dataset.editEntry), key=input.dataset.editKey;
        const entry=state.entries[index];
        if (!entry || !['title','route','summary','previewText'].includes(key)) return;
        entry[key]=input.value;
        document.querySelectorAll('[data-entry]').forEach(node => {
            if(Number(node.dataset.entry)!==index) return;
            node.querySelectorAll('[data-entry-field]').forEach(field => {if(field.dataset.entryField===key)field.textContent=input.value;});
            if(key==='title')node.querySelector('[data-opening-index]').setAttribute('aria-label','预览开场：'+input.value);
        });
        if (route.view==='reader' && route.index===index) {
            fillReader(index);
            if(key==='title')document.title=(input.value||'未命名开场')+' · '+editionName;
        }
    }));
    renderRoute(true);
})(___JIUYI_STATE___,"flight","双幅飞鸟",function resolveEditionRoute(hash, count, theme) {
    const path = String(hash || '').replace(/^#/, '');
    const match = /^opening\/(0|[1-9]\d*)$/.exec(path);
    if (match && Number(match[1]) < count) return {view:'reader', index:Number(match[1])};
    if (theme === 'flight') {
        if (path === 'about') return {view:'about', index:null};
        if (path === 'contents' || path === 'pages') return {view:'contents', index:null};
        return {view:'cover', index:null};
    }
    if (path === 'pages' || theme === 'cobalt') return {view:'pages', index:null};
    return {view:'cover', index:null};
});
